using SerialStudio.Core;
namespace SerialStudio;

/// Managed buffers and native ABI declarations are generated by Interoptopus.
internal static class RustCore
{
    private static void Check(string? error) { if (error is not null) throw new InvalidOperationException(error); }
    internal static void Shutdown() { using var wire = Interop.serial_studio_disconnect().AsOk(); Check(wire.Unwire().error); }
    internal static Task<List<PortInfo>> Ports() => Task.Run(() =>
    {
        using var wire = Interop.serial_studio_ports().AsOk();
        var response = wire.Unwire(); Check(response.error); return response.payload;
    });
    internal static Task<PollBatch> Poll() => Task.Run(() =>
    {
        using var wire = Interop.serial_studio_poll().AsOk();
        var response = wire.Unwire(); Check(response.error); return response.payload ?? throw new InvalidOperationException("核心未返回串口状态");
    });
    internal static Task<SerialStatus> Connect(string path, SerialConfig config) => UpdateActivity.Run(() =>
    {
        using var request = new ConnectRequest { path = path, config = config }.Wire();
        using var wire = Interop.serial_studio_connect(request).AsOk();
        var response = wire.Unwire(); Check(response.error);
        var status = response.payload ?? throw new InvalidOperationException("核心未返回连接状态");
        UpdateActivity.SetConnected(status.connected); return status;
    });
    internal static Task<SerialStatus> Disconnect() => UpdateActivity.Run(() =>
    {
        using var wire = Interop.serial_studio_disconnect().AsOk();
        var response = wire.Unwire(); Check(response.error);
        var status = response.payload ?? throw new InvalidOperationException("核心未返回连接状态");
        UpdateActivity.SetConnected(status.connected); return status;
    });
    internal static Task Send(string text, SendFormat format, LineEnding lineEnding) => UpdateActivity.Run(() =>
    {
        using var request = new SendRequest { text = text, format = format, line_ending = lineEnding }.Wire();
        using var wire = Interop.serial_studio_send(request).AsOk(); Check(wire.Unwire().error);
    });
}
